import pandas as pd
import numpy as np

files = [experiment_1_csv, experiment_2_csv, experiment_3_csv, experiment_4_csv, experiment_5_csv]
dfs = []
for f in files:
    try:
        dfs.append(pd.read_csv(f))
    except Exception as e:
        print(f"Error reading {f}: {e}")

df = pd.concat(dfs, ignore_index=True)
print("Shape:", df.shape)
print("Columns:", df.columns.tolist())
print("\nNumeric correlation with ReadmissionRate:")
numeric_cols = df.select_dtypes(include=[np.number]).columns
if "ReadmissionRate" in numeric_cols:
    print(df[numeric_cols].corr()["ReadmissionRate"].sort_values())
else:
    print("ReadmissionRate not found in numeric columns")

print("\nUnique values for categorical-looking columns:")
for c in df.columns:
    if df[c].dtype == 'object' or df[c].nunique() < 5:
        print(f"{c}: {sorted(df[c].dropna().unique())}")
